"""Canonical corruption dispatch over the vendored imagecorruptions closure.

Exposes exactly the five frozen IDs (no aliases), validates the input contract, derives a
deterministic per-item seed, isolates NumPy's global RNG, and canonicalises every result to a
uint8 H*W*3 RGB array — upstream returns a PIL Image for `jpeg_compression` and float arrays
elsewhere, so canonicalisation happens strictly AFTER the unchanged upstream calculation.

SEED POLICY (thesis implementation choice, not an upstream feature). `src/seeds.py` freezes only the
global seed 42 and defines no corruption-specific rule, so this module locks:

    item_seed = uint32 from SHA-256 of the canonical JSON serialisation of
                ["plantseg-corruption-v1", 42, image_id, corruption_id, severity]

    encoding      : UTF-8, json.dumps(..., separators=(",", ":"), ensure_ascii=True, sort_keys=False)
    extraction    : int.from_bytes(digest[:4], "big") & 0xFFFFFFFF
    image_id norm : str(image_id).strip()

`hash()` is never used (it is process-randomised). Each item is independently reproducible, so
regeneration order cannot change bytes and repairing one cache entry perturbs no other.

SEVERITIES, PER CORRUPTION (AM-16 item 6, docs/PREREGISTRATION_AMENDMENTS.md :303-306). motion_blur,
jpeg_compression, brightness and fog are generated at severities 1-5; gaussian_noise at 1-4 only.
(gaussian_noise, 5) is the one excluded cell and is refused here. `SEVERITIES_BY_CORRUPTION` is an
independent copy of the protocol's scored sets (configs/corruption_protocol.json, parsed by
`src.corruption_roles`); the cache generator refuses to run when the two disagree.
"""

from __future__ import annotations

import contextlib
import hashlib
import json
from types import MappingProxyType

import numpy as np
from PIL import Image

from . import corruptions as _c
from .provenance import SEED_POLICY_ID, verify_vendor_integrity

MASTER_SEED = 42
CORRUPTION_IDS = ("motion_blur", "gaussian_noise", "jpeg_compression", "brightness", "fog")
SEVERITIES_BY_CORRUPTION = MappingProxyType({
    "motion_blur": (1, 2, 3, 4, 5),
    "gaussian_noise": (1, 2, 3, 4),
    "jpeg_compression": (1, 2, 3, 4, 5),
    "brightness": (1, 2, 3, 4, 5),
    "fog": (1, 2, 3, 4, 5),
})
EXCLUDED_CELLS = (("gaussian_noise", 5),)

_DISPATCH = {
    "motion_blur": _c.motion_blur,
    "gaussian_noise": _c.gaussian_noise,
    "jpeg_compression": _c.jpeg_compression,
    "brightness": _c.brightness,
    "fog": _c.fog,
}


class CorruptionInputError(ValueError):
    """A rejected corruption request or malformed image input."""


def canonical_seed_payload(image_id: str, corruption_id: str, severity: int) -> bytes:
    """The exact bytes hashed to derive an item seed. Documented and platform-independent."""
    tuple_ = [SEED_POLICY_ID, MASTER_SEED, str(image_id).strip(), corruption_id, int(severity)]
    return json.dumps(tuple_, separators=(",", ":"), ensure_ascii=True).encode("utf-8")


def item_seed(image_id: str, corruption_id: str, severity: int) -> int:
    """Deterministic uint32 seed for one (image, corruption, severity) cell."""
    digest = hashlib.sha256(canonical_seed_payload(image_id, corruption_id, severity)).digest()
    return int.from_bytes(digest[:4], "big") & 0xFFFFFFFF


@contextlib.contextmanager
def numpy_seed(seed: int):
    """Seed NumPy's global RNG for one call and ALWAYS restore the caller's state."""
    state = np.random.get_state()
    try:
        np.random.seed(seed)
        yield
    finally:
        np.random.set_state(state)


def validate_request(image: np.ndarray, corruption_id: str, severity: int, *,
                     lift_floor: bool = False) -> None:
    """Refuse a request upstream's corrupt() would refuse, plus the excluded cell.

    `lift_floor` lifts upstream's 32-px floor for this one image (L-CORR, LC7): the cache generator
    sets it only for an image whose resized short side is below the floor, and records that
    image_id in the manifest's `floor_lifted`. Every other check still applies.
    """
    if corruption_id not in _DISPATCH:
        raise CorruptionInputError(
            f"unknown corruption {corruption_id!r}; the frozen vocabulary is {CORRUPTION_IDS} "
            "and aliases are rejected")
    if (corruption_id, severity) in EXCLUDED_CELLS:
        raise CorruptionInputError(
            f"{corruption_id} at severity {severity} is never generated by the official pipeline: "
            "AM-16 item 6 adds severity 5 only for the four non-noise corruptions")
    allowed = SEVERITIES_BY_CORRUPTION[corruption_id]
    if severity not in allowed:
        raise CorruptionInputError(
            f"severity must be one of {allowed} for {corruption_id}, got {severity}")
    if not isinstance(image, np.ndarray) or image.dtype != np.uint8:
        raise CorruptionInputError(
            f"corruption operates on uint8 RGB, got "
            f"{getattr(image, 'dtype', type(image).__name__)}")
    if image.ndim != 3 or image.shape[2] != 3:
        raise CorruptionInputError(f"expected H*W*3 RGB, got {getattr(image, 'shape', None)}")
    if not lift_floor and min(image.shape[:2]) < MIN_SIDE:
        raise CorruptionInputError(
            f"upstream requires both sides >= {MIN_SIDE}px, got {image.shape[:2]}")


MIN_SIDE = 32          # upstream refuses images smaller than 32 px on either side


def _canonicalise(out, shape) -> np.ndarray:
    """Upstream result -> uint8 H*W*3 RGB, mirroring upstream `corrupt()`'s `np.uint8(...)` wrap.

    Applied strictly AFTER the unchanged upstream calculation. `jpeg_compression` returns a PIL
    Image and the others return float arrays, so this is the single place both become canonical.
    """
    arr = np.uint8(out)                      # exactly upstream corrupt()'s final conversion
    if arr.shape != shape:
        raise CorruptionInputError(f"corruption changed the image shape: {arr.shape} != {shape}")
    return np.ascontiguousarray(arr, dtype=np.uint8)


def apply_corruption(image: np.ndarray, corruption_id: str, severity: int, *,
                     image_id: str, verify_integrity: bool = True,
                     lift_floor: bool = False) -> tuple[np.ndarray, int]:
    """Apply one registered corruption deterministically. Returns `(uint8 array, item_seed)`.

    The mask is never passed in and therefore can never be altered here. `lift_floor`: see
    validate_request.
    """
    if verify_integrity:
        verify_vendor_integrity()
    validate_request(image, corruption_id, severity, lift_floor=lift_floor)
    seed = item_seed(image_id, corruption_id, severity)
    # Upstream `corrupt()` feeds every corruption a PIL Image (`Image.fromarray(image)`); mirror
    # that exactly so the vendored numerics see their expected input type.
    pil = Image.fromarray(image)
    with numpy_seed(seed):
        out = _DISPATCH[corruption_id](pil, severity)
    return _canonicalise(out, image.shape), seed


__all__ = ["CORRUPTION_IDS", "EXCLUDED_CELLS", "MASTER_SEED", "SEED_POLICY_ID",
           "SEVERITIES_BY_CORRUPTION", "CorruptionInputError", "apply_corruption", "item_seed",
           "canonical_seed_payload", "numpy_seed", "validate_request", "verify_vendor_integrity"]
